import { describe, expect, it, jest } from "@jest/globals";
import * as normalize from "../normalize";
import { syncCalendar } from "../syncCalendar";
import { FakeCalendarApi } from "./fakeCalendarApi";

const events = [
  { id: "e1", start: "2024-06-01T09:00:00Z", end: "2024-06-01T10:00:00Z", title: "Standup" },
  { id: "e2", start: "2024-06-01T13:00:00Z", end: "2024-06-01T14:00:00Z", title: "Review" },
];

describe("syncCalendar", () => {
  it("returns one entry per upstream event", async () => {
    const api = new FakeCalendarApi(events);
    const result = await syncCalendar(api, "cal_1");
    expect(result.entries).toHaveLength(2);
  });

  it("keeps the upstream id on each entry", async () => {
    const api = new FakeCalendarApi(events);
    const result = await syncCalendar(api, "cal_1");
    expect(result.entries.map((e) => e.sourceId)).toEqual(["e1", "e2"]);
  });

  it("normalizes every event in upstream order", async () => {
    const spy = jest.spyOn(normalize, "normalizeEvent");
    const api = new FakeCalendarApi(events);

    await syncCalendar(api, "cal_1");

    expect(spy).toHaveBeenNthCalledWith(1, events[0]);
    expect(spy).toHaveBeenNthCalledWith(2, events[1]);
  });

  it("reports zero entries for an empty calendar", async () => {
    const result = await syncCalendar(new FakeCalendarApi([]), "cal_1");
    expect(result.entries).toEqual([]);
  });
});

