import { describe, expect, it, beforeAll } from "@jest/globals";
import request from "supertest";
import { createApp } from "../src/app";
import { seedInvoice } from "./helpers/seed";

const lines = [
  { description: "Design", qty: 3, unitCents: 12000 },
  { description: "Hosting", qty: 12, unitCents: 1500 },
];
const TAX_RATE = 0.2;

describe("GET /api/invoices/:id/total", () => {
  let app: ReturnType<typeof createApp>;
  let invoiceId: string;

  beforeAll(async () => {
    app = createApp({ db: ":memory:" });
    invoiceId = await seedInvoice(app, { lines, taxRate: TAX_RATE });
  });

  it("returns the taxed total in cents", async () => {
    const subtotal = lines.reduce((sum, l) => sum + l.qty * l.unitCents, 0);
    const expectedTotal = Math.round(subtotal * (1 + TAX_RATE));

    const res = await request(app).get(`/api/invoices/${invoiceId}/total`);

    expect(res.status).toBe(200);
    expect(res.body.totalCents).toBe(expectedTotal);
  });

  it("404s for an unknown invoice", async () => {
    const res = await request(app).get("/api/invoices/inv_missing/total");
    expect(res.status).toBe(404);
  });
});

